import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts - users shouldn't feel the machinery beneath
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [{ id: '1', name: 'Starfleet Uniform', price: 99.99 }];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 99.99, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - The User Journey', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  describe('Happy Path - Complete Checkout Flow', () => {
    it('guides users through shipping, payment, review to confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Shipping step - user needs clarity
      await user.type(screen.getByLabelText(/street address/i), '123 Enterprise Way');
      await user.type(screen.getByLabelText(/city/i), 'San Francisco');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '94102');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step - handle with care, users feel vulnerable here
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Jean-Luc Picard');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review - users need reassurance
      expect(screen.getByText(/starfleet uniform/i)).toBeInTheDocument();
      expect(screen.getByText(/\$99\.99/)).toBeInTheDocument();

      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation - the emotional payoff
      await waitFor(() => {
        expect(screen.getByRole('status')).toHaveTextContent(/order confirmed/i);
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  describe('Validation - Users Need Gentle Guidance', () => {
    it('displays inline errors for invalid shipping fields', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert', { name: /street address is required/i })).toBeInTheDocument();
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('rejects malformed ZIP codes without blame', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('Error States - Users Deserve Compassion', () => {
    it('shows payment failure with path to recovery', async () => {
      mockProcessPayment.mockRejectedValue(new Error('Card declined'));
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to review step (abbreviated)
      // ... fill forms ...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });
      expect(screen.getByRole('button', { name: /back/i })).toBeEnabled();
    });
  });

  describe('Loading States - Users Need Patience Signals', () => {
    it('disables actions and shows processing during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      // ... navigate to review ...

      await userEvent.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    });
  });

  describe('Accessibility - All Users Deserve Welcome', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });

    it('provides clear progress indication', () => {
      render(<Checkout />);
      expect(screen.getByRole('navigation', { name: /checkout progress/i })).toBeInTheDocument();
      expect(screen.getByText('Shipping')).toHaveAttribute('aria-current', 'step');
    });
  });

  describe('Edge Cases - Hidden Needs', () => {
    it('handles empty cart gracefully', () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout onCancel={vi.fn()} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });
});
